-- =====================================================================
--  Valorant esports - schéma relationnel pour le recrutement d'équipe
--  Source : API vlr.gg (matches, events, joueurs, classements, news)
--
--  DDL volontairement portable (SQLite 3.25+ / PostgreSQL 13+).
--  Adaptations PostgreSQL conseillées :
--    * TIMESTAMP -> TIMESTAMPTZ (les heures sont stockées en UTC)
--    * etl_issues.issue_id -> GENERATED BY DEFAULT AS IDENTITY
--    * raw_ingest.payload  -> JSONB
--    * BOOLEAN : 0/1 en SQLite, true/false en PostgreSQL
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. DIMENSIONS
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS teams (
    team_id        INTEGER PRIMARY KEY,
    vlr_team_id    INTEGER UNIQUE,              -- NULL si l'équipe n'est connue que par son nom
    name           TEXT    NOT NULL,
    name_norm      TEXT    NOT NULL,            -- minuscule, sans accents (clé de rapprochement)
    short_tag      TEXT,                        -- ex. '100T', 'G2'
    country_code   TEXT,                        -- issu des drapeaux (us, kr, eu...)
    country_name   TEXT,                        -- issu des classements / prizes
    logo_url       TEXT
);
CREATE INDEX IF NOT EXISTS idx_teams_name_norm ON teams(name_norm);

CREATE TABLE IF NOT EXISTS team_aliases (
    alias_norm TEXT    NOT NULL,
    team_id    INTEGER NOT NULL REFERENCES teams(team_id) ON DELETE CASCADE,
    alias      TEXT    NOT NULL,
    PRIMARY KEY (alias_norm, team_id)
);

CREATE TABLE IF NOT EXISTS players (
    player_id          INTEGER PRIMARY KEY,
    vlr_player_id      INTEGER UNIQUE,          -- NULL tant que le joueur n'a pas été rapproché d'un profil
    ign                TEXT    NOT NULL,        -- pseudo en jeu
    ign_norm           TEXT    NOT NULL,
    real_name          TEXT,
    country_code       TEXT,
    current_team_id    INTEGER REFERENCES teams(team_id),
    avatar_url         TEXT,
    total_winnings_usd INTEGER
);
CREATE INDEX IF NOT EXISTS idx_players_ign_norm ON players(ign_norm);

CREATE TABLE IF NOT EXISTS player_social_links (
    player_id INTEGER NOT NULL REFERENCES players(player_id) ON DELETE CASCADE,
    platform  TEXT    NOT NULL,
    url       TEXT    NOT NULL,
    PRIMARY KEY (player_id, platform)
);

-- Historique joueur <-> équipe, avec la source de l'information
CREATE TABLE IF NOT EXISTS player_team_membership (
    player_id       INTEGER NOT NULL REFERENCES players(player_id) ON DELETE CASCADE,
    team_id         INTEGER NOT NULL REFERENCES teams(team_id)     ON DELETE CASCADE,
    source          TEXT    NOT NULL,           -- match | event_roster | profile | profile_past | player_matches
    first_seen_date DATE,
    last_seen_date  DATE,
    is_current      BOOLEAN,
    note            TEXT,
    PRIMARY KEY (player_id, team_id, source)
);
CREATE INDEX IF NOT EXISTS idx_membership_team ON player_team_membership(team_id);

CREATE TABLE IF NOT EXISTS events (
    event_id        INTEGER PRIMARY KEY,
    vlr_event_id    INTEGER UNIQUE,
    name            TEXT NOT NULL,
    name_norm       TEXT NOT NULL,
    subtitle        TEXT,
    region          TEXT,
    status          TEXT,                       -- upcoming | ongoing | completed
    start_date      DATE,
    end_date        DATE,
    prize_pool_usd  INTEGER,
    location        TEXT,
    logo_url        TEXT
);
CREATE INDEX IF NOT EXISTS idx_events_name_norm ON events(name_norm);

CREATE TABLE IF NOT EXISTS event_teams (        -- classement final / dotation par équipe
    event_id        INTEGER NOT NULL REFERENCES events(event_id) ON DELETE CASCADE,
    team_id         INTEGER NOT NULL REFERENCES teams(team_id)   ON DELETE CASCADE,
    placement_label TEXT,                       -- '1st', '5th-8th'
    placement_rank  INTEGER,                    -- 1, 5 (borne basse de la fourchette)
    prize_usd       INTEGER,
    qualification   TEXT,
    PRIMARY KEY (event_id, team_id)
);

CREATE TABLE IF NOT EXISTS event_rosters (      -- composition d'une équipe sur un événement
    event_id  INTEGER NOT NULL REFERENCES events(event_id)   ON DELETE CASCADE,
    team_id   INTEGER NOT NULL REFERENCES teams(team_id)     ON DELETE CASCADE,
    player_id INTEGER NOT NULL REFERENCES players(player_id) ON DELETE CASCADE,
    PRIMARY KEY (event_id, team_id, player_id)
);

CREATE TABLE IF NOT EXISTS player_event_placements (
    player_id       INTEGER NOT NULL REFERENCES players(player_id) ON DELETE CASCADE,
    event_id        INTEGER NOT NULL REFERENCES events(event_id)   ON DELETE CASCADE,
    team_id         INTEGER REFERENCES teams(team_id),
    series          TEXT,
    placement_label TEXT,
    placement_rank  INTEGER,
    prize_usd       INTEGER,
    year            INTEGER,
    PRIMARY KEY (player_id, event_id)
);

CREATE TABLE IF NOT EXISTS game_maps (
    map_id INTEGER PRIMARY KEY,
    name   TEXT NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS agents (
    agent_id INTEGER PRIMARY KEY,
    name     TEXT NOT NULL UNIQUE,
    role     TEXT                               -- duelist | initiator | controller | sentinel (à renseigner)
);

-- ---------------------------------------------------------------------
-- 2. MATCHS (niveau match -> map -> round)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS matches (
    match_id       INTEGER PRIMARY KEY,         -- id vlr.gg
    event_id       INTEGER REFERENCES events(event_id),
    event_label    TEXT,                        -- libellé brut quand l'événement n'est pas rapprochable
    stage          TEXT,                        -- 'Playoffs: Upper Quarterfinals'
    status         TEXT NOT NULL CHECK (status IN ('upcoming','live','final')),
    detail_level   TEXT NOT NULL CHECK (detail_level IN ('stub','summary','full')),
    match_date     DATE,
    scheduled_at   TIMESTAMP,                   -- UTC
    patch          TEXT,
    team1_id       INTEGER REFERENCES teams(team_id),
    team2_id       INTEGER REFERENCES teams(team_id),
    team1_score    INTEGER,                     -- score en maps
    team2_score    INTEGER,
    winner_team_id INTEGER REFERENCES teams(team_id),
    url            TEXT,
    CHECK (team1_id IS NULL OR team2_id IS NULL OR team1_id <> team2_id)
);
CREATE INDEX IF NOT EXISTS idx_matches_event ON matches(event_id);
CREATE INDEX IF NOT EXISTS idx_matches_team1 ON matches(team1_id);
CREATE INDEX IF NOT EXISTS idx_matches_team2 ON matches(team2_id);
CREATE INDEX IF NOT EXISTS idx_matches_date  ON matches(match_date);

CREATE TABLE IF NOT EXISTS match_map_vetos (
    match_id INTEGER NOT NULL REFERENCES matches(match_id) ON DELETE CASCADE,
    step     INTEGER NOT NULL,
    team_id  INTEGER REFERENCES teams(team_id),  -- NULL pour le decider
    action   TEXT    NOT NULL CHECK (action IN ('ban','pick','decider')),
    map_id   INTEGER NOT NULL REFERENCES game_maps(map_id),
    PRIMARY KEY (match_id, step)
);

CREATE TABLE IF NOT EXISTS match_vods (
    match_id   INTEGER NOT NULL REFERENCES matches(match_id) ON DELETE CASCADE,
    url        TEXT    NOT NULL,
    label      TEXT,
    map_number INTEGER,                         -- NULL = VOD du match complet
    PRIMARY KEY (match_id, url)
);

CREATE TABLE IF NOT EXISTS match_maps (
    match_map_id      INTEGER PRIMARY KEY,      -- match_id * 10 + map_number (déterministe)
    match_id          INTEGER NOT NULL REFERENCES matches(match_id) ON DELETE CASCADE,
    map_number        INTEGER NOT NULL,
    map_id            INTEGER REFERENCES game_maps(map_id),
    picked_by_team_id INTEGER REFERENCES teams(team_id),
    duration_seconds  INTEGER,
    team1_score       INTEGER,
    team2_score       INTEGER,
    team1_score_ct    INTEGER,
    team1_score_t     INTEGER,
    team2_score_ct    INTEGER,
    team2_score_t     INTEGER,
    team1_score_ot    INTEGER,
    team2_score_ot    INTEGER,
    rounds_played     INTEGER,
    rounds_complete   BOOLEAN,                  -- faux si la liste des rounds ne correspond pas au score (ex. prolongations tronquées)
    team1_start_side  TEXT CHECK (team1_start_side IN ('ct','t')),
    winner_team_id    INTEGER REFERENCES teams(team_id),
    UNIQUE (match_id, map_number)
);
CREATE INDEX IF NOT EXISTS idx_match_maps_map ON match_maps(map_id);

CREATE TABLE IF NOT EXISTS rounds (
    match_map_id   INTEGER NOT NULL REFERENCES match_maps(match_map_id) ON DELETE CASCADE,
    round_number   INTEGER NOT NULL,
    winner_team_id INTEGER NOT NULL REFERENCES teams(team_id),
    winner_side    TEXT CHECK (winner_side IN ('ct','t')),   -- camp de l'équipe gagnante
    PRIMARY KEY (match_map_id, round_number)
);

-- ---------------------------------------------------------------------
-- 3. PERFORMANCES JOUEURS
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS player_map_stats (   -- scoreboard par joueur et par map
    match_map_id INTEGER NOT NULL REFERENCES match_maps(match_map_id) ON DELETE CASCADE,
    player_id    INTEGER NOT NULL REFERENCES players(player_id),
    team_id      INTEGER NOT NULL REFERENCES teams(team_id),
    agent_id     INTEGER REFERENCES agents(agent_id),
    rating       REAL,
    acs          INTEGER,
    kills        INTEGER,
    deaths       INTEGER,
    assists      INTEGER,
    kd_diff      INTEGER,
    kast_pct     REAL,
    adr          REAL,
    hs_pct       REAL,
    first_kills  INTEGER,
    first_deaths INTEGER,
    fk_diff      INTEGER,
    PRIMARY KEY (match_map_id, player_id)
);
CREATE INDEX IF NOT EXISTS idx_pms_player ON player_map_stats(player_id);
CREATE INDEX IF NOT EXISTS idx_pms_team   ON player_map_stats(team_id);

CREATE TABLE IF NOT EXISTS player_match_advanced (  -- agrégé sur tout le match (voir note qualité)
    match_id     INTEGER NOT NULL REFERENCES matches(match_id) ON DELETE CASCADE,
    player_id    INTEGER NOT NULL REFERENCES players(player_id),
    team_id      INTEGER REFERENCES teams(team_id),
    k2           INTEGER, k3 INTEGER, k4 INTEGER, k5 INTEGER,            -- multi-kills
    clutch_1v1   INTEGER, clutch_1v2 INTEGER, clutch_1v3 INTEGER,
    clutch_1v4   INTEGER, clutch_1v5 INTEGER,
    econ_rating  INTEGER,
    plants       INTEGER,
    defuses      INTEGER,
    PRIMARY KEY (match_id, player_id)
);

CREATE TABLE IF NOT EXISTS player_duels (       -- matrice de kills, une ligne par sens
    match_id    INTEGER NOT NULL REFERENCES matches(match_id) ON DELETE CASCADE,
    player_id   INTEGER NOT NULL REFERENCES players(player_id),
    opponent_id INTEGER NOT NULL REFERENCES players(player_id),
    kills       INTEGER NOT NULL,               -- kills de player sur opponent
    deaths      INTEGER NOT NULL,               -- kills de opponent sur player
    PRIMARY KEY (match_id, player_id, opponent_id)
);

CREATE TABLE IF NOT EXISTS team_map_economy (   -- uniquement quand la donnée est validée
    match_map_id        INTEGER NOT NULL REFERENCES match_maps(match_map_id) ON DELETE CASCADE,
    team_id             INTEGER NOT NULL REFERENCES teams(team_id),
    pistol_won          INTEGER,
    eco_played          INTEGER, eco_won          INTEGER,
    semi_eco_played     INTEGER, semi_eco_won     INTEGER,
    semi_buy_played     INTEGER, semi_buy_won     INTEGER,
    full_buy_played     INTEGER, full_buy_won     INTEGER,
    PRIMARY KEY (match_map_id, team_id)
);

CREATE TABLE IF NOT EXISTS h2h_history (        -- bloc head_to_head tel que renvoyé par l'API
    match_id      INTEGER NOT NULL REFERENCES matches(match_id) ON DELETE CASCADE,
    ref_match_id  INTEGER NOT NULL,
    played_on     DATE,
    team_a_name   TEXT,                         -- '' = équipe de la page match
    team_b_name   TEXT,
    team_a_won    BOOLEAN,
    team_b_won    BOOLEAN,
    score_text    TEXT,
    event_label   TEXT,
    url           TEXT,
    PRIMARY KEY (match_id, ref_match_id)
);

CREATE TABLE IF NOT EXISTS player_matches (     -- historique d'un joueur (endpoint player_matches)
    player_id INTEGER NOT NULL REFERENCES players(player_id) ON DELETE CASCADE,
    match_id  INTEGER NOT NULL REFERENCES matches(match_id)  ON DELETE CASCADE,
    team_id   INTEGER REFERENCES teams(team_id),
    result    TEXT CHECK (result IN ('win','loss')),
    PRIMARY KEY (player_id, match_id)
);

-- ---------------------------------------------------------------------
-- 4. SNAPSHOTS (classements, stats agrégées) et CONTENU
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS team_rankings (
    snapshot_date   DATE    NOT NULL,
    region          TEXT    NOT NULL,           -- 'la-s', 'eu', 'ap'...
    team_id         INTEGER NOT NULL REFERENCES teams(team_id),
    rank            INTEGER NOT NULL,
    rating          INTEGER,
    streak_type     TEXT CHECK (streak_type IN ('W','L')),
    streak_length   INTEGER,
    wins            INTEGER,
    losses          INTEGER,
    recent_wins     INTEGER,
    recent_losses   INTEGER,
    earnings_usd    INTEGER,
    days_since_last_match INTEGER,
    last_opponent   TEXT,
    PRIMARY KEY (snapshot_date, region, team_id)
);

CREATE TABLE IF NOT EXISTS player_stats_snapshot (   -- endpoint stats (agrégé par région / période)
    snapshot_date  DATE    NOT NULL,
    region         TEXT    NOT NULL,
    timespan_days  INTEGER NOT NULL,
    player_id      INTEGER NOT NULL REFERENCES players(player_id),
    team_id        INTEGER REFERENCES teams(team_id),
    agents         TEXT,
    rounds_played  INTEGER,
    rating         REAL, acs REAL, kd REAL, kast_pct REAL, adr REAL,
    kpr REAL, apr REAL, fkpr REAL, fdpr REAL, hs_pct REAL, clutch_pct REAL,
    extra_json     TEXT,
    PRIMARY KEY (snapshot_date, region, timespan_days, player_id)
);

CREATE TABLE IF NOT EXISTS player_agent_stats (
    player_id  INTEGER NOT NULL REFERENCES players(player_id) ON DELETE CASCADE,
    agent_id   INTEGER NOT NULL REFERENCES agents(agent_id),
    usage      REAL, rounds REAL, rating REAL, acs REAL, kd REAL,
    adr REAL, kast_pct REAL, extra_json TEXT,
    PRIMARY KEY (player_id, agent_id)
);

CREATE TABLE IF NOT EXISTS news_articles (
    news_id        INTEGER PRIMARY KEY,         -- id vlr.gg extrait de l'URL
    title          TEXT NOT NULL,
    description    TEXT,
    author         TEXT,
    published_date DATE,
    url            TEXT
);

-- ---------------------------------------------------------------------
-- 5. TRAÇABILITÉ ETL
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS raw_ingest (         -- payloads bruts pour retraiter sans rappeler l'API
    source       TEXT NOT NULL,
    payload_sha1 TEXT NOT NULL,
    ingested_at  TIMESTAMP NOT NULL,
    payload      TEXT NOT NULL,
    PRIMARY KEY (source, payload_sha1)
);

CREATE TABLE IF NOT EXISTS etl_issues (         -- anomalies de qualité détectées
    issue_id    INTEGER PRIMARY KEY,
    created_at  TIMESTAMP NOT NULL,
    severity    TEXT NOT NULL CHECK (severity IN ('info','warning','error')),
    source      TEXT,
    entity_key  TEXT,
    code        TEXT NOT NULL,
    detail      TEXT
);

-- ---------------------------------------------------------------------
-- 6. VUES POUR L'APPLICATION
-- ---------------------------------------------------------------------
CREATE VIEW IF NOT EXISTS v_player_performance AS
SELECT  p.player_id,
        p.ign,
        p.country_code,
        COUNT(*)                                   AS maps_played,
        AVG(s.rating)                              AS avg_rating,
        AVG(s.acs)                                 AS avg_acs,
        1.0 * SUM(s.kills) / NULLIF(SUM(s.deaths), 0) AS kd_ratio,
        AVG(s.kast_pct)                            AS avg_kast_pct,
        AVG(s.adr)                                 AS avg_adr,
        AVG(s.hs_pct)                              AS avg_hs_pct,
        SUM(s.first_kills)                         AS first_kills,
        SUM(s.first_deaths)                        AS first_deaths
FROM player_map_stats s
JOIN players p ON p.player_id = s.player_id
GROUP BY p.player_id, p.ign, p.country_code;

CREATE VIEW IF NOT EXISTS v_team_map_record AS
SELECT  t.team_id,
        t.name AS team_name,
        gm.name AS map_name,
        COUNT(*) AS maps_played,
        SUM(CASE WHEN mm.winner_team_id = t.team_id THEN 1 ELSE 0 END) AS maps_won
FROM match_maps mm
JOIN matches m    ON m.match_id = mm.match_id
JOIN teams t      ON t.team_id IN (m.team1_id, m.team2_id)
JOIN game_maps gm ON gm.map_id = mm.map_id
GROUP BY t.team_id, t.name, gm.name;

CREATE VIEW IF NOT EXISTS v_player_latest_team AS
SELECT player_id, team_id, source, last_seen_date
FROM (
    SELECT  pm.*,
            ROW_NUMBER() OVER (PARTITION BY pm.player_id
                               ORDER BY pm.is_current DESC, pm.last_seen_date DESC) AS rn
    FROM player_team_membership pm
) x
WHERE rn = 1;
